INSERT INTO `correos_enviados` VALUES ('CO-2026-DEMO0007','SOL-2026-DEMO0007','julio.xicara@ejemplo.gt','Asilo Cabeza de Algodon · Tránsito Xicará Tzoc fue remitido a Cardiologia','Estimado/a Julio Xicará, sobrino:\n\nLe escribimos del Asilo de Ancianos \"Cabeza de Algodon\" para informarle\nque su familiar Tránsito Xicará Tzoc (ASL-007) fue remitido a una consulta con especialista.\n\n  Numero de solicitud : SOL-2026-DEMO0007\n  Especialidad        : Cardiologia\n  Motivo              : Cifras de presion arterial elevadas en los ultimos tres controles, pese al tratamiento con enalapril.\n  Remitido por        : Dr. Angel Maltez\n  Fecha de la remision: 22/10/2026 a las 09:00\n  Estado actual       : PENDIENTE de que la fundacion le asigne medico y hora\n\nLo acompaña: Enf. Lucia Tzoc.\n\nCuando la fundacion le asigne medico, fecha y hora, se le informara el\ndetalle de la cita. Si necesita acompañar a su familiar ese dia, puede\ncomunicarse con la administracion del asilo.\n\nAtentamente,\nAsilo de Ancianos \"Cabeza de Algodon\"\nMazatenango, Suchitepequez\n','2026-10-22 09:00:00','REGISTRADO'),('CO-2026-DEMO0014','SOL-2026-DEMO0014','maria.coy@ejemplo.gt','Asilo Cabeza de Algodon · Rosalía Menchú Coy fue remitido a Psiquiatria','Estimado/a María Coy, hija:\n\nLe escribimos del Asilo de Ancianos \"Cabeza de Algodon\" para informarle\nque su familiar Rosalía Menchú Coy (ASL-014) fue remitido a una consulta con especialista.\n\n  Numero de solicitud : SOL-2026-DEMO0014\n  Especialidad        : Psiquiatria\n  Motivo              : Agitacion nocturna que no cede con el ajuste de la rutina de sueño.\n  Remitido por        : Dr. Angel Maltez\n  Fecha de la remision: 20/10/2026 a las 09:00\n  Estado actual       : PENDIENTE de que la fundacion le asigne medico y hora\n\nLo acompaña: Enf. Lucia Tzoc.\n\nCuando la fundacion le asigne medico, fecha y hora, se le informara el\ndetalle de la cita. Si necesita acompañar a su familiar ese dia, puede\ncomunicarse con la administracion del asilo.\n\nAtentamente,\nAsilo de Ancianos \"Cabeza de Algodon\"\nMazatenango, Suchitepequez\n','2026-10-20 09:00:00','REGISTRADO'),('CO-2026-DEMO0022','SOL-2026-DEMO0022','elena.ixcoy@ejemplo.gt','Asilo Cabeza de Algodon · Bernardo Puac Ixcoy fue remitido a Cardiologia','Estimado/a Elena Ixcoy, nieta:\n\nLe escribimos del Asilo de Ancianos \"Cabeza de Algodon\" para informarle\nque su familiar Bernardo Puac Ixcoy (ASL-022) fue remitido a una consulta con especialista.\n\n  Numero de solicitud : SOL-2026-DEMO0022\n  Especialidad        : Cardiologia\n  Motivo              : Control de anticoagulacion por fibrilacion auricular.\n  Remitido por        : Dr. Angel Maltez\n  Fecha de la remision: 12/10/2026 a las 09:00\n  Estado actual       : PENDIENTE de que la fundacion le asigne medico y hora\n\nLo acompaña: Enf. Lucia Tzoc.\n\nCuando la fundacion le asigne medico, fecha y hora, se le informara el\ndetalle de la cita. Si necesita acompañar a su familiar ese dia, puede\ncomunicarse con la administracion del asilo.\n\nAtentamente,\nAsilo de Ancianos \"Cabeza de Algodon\"\nMazatenango, Suchitepequez\n','2026-10-12 09:00:00','REGISTRADO');
/*!40000 ALTER TABLE `correos_enviados` ENABLE KEYS */;
UNLOCK TABLES;

